#!/usr/bin/env python3
"""VBA module writer/injector for the T046 dashboard (xlsx).

Status: EXPERIMENTAL — T046 [xlsx], review requested.

Writing a `.bas` module is portable.  Injecting it into a macro-enabled
workbook needs Windows + Excel + "Trust access to the VBA project object model";
when that gate is closed, the module stays a labelled artifact and the workbook
remains `.xlsx`.  Never silently pretend a macro is embedded.
"""
from __future__ import annotations

from pathlib import Path
import sys

MODULE = r'''Attribute VB_Name = "DashboardTools"
' T046 dashboard helper. Generated by Sheet Forge; review before production.
Option Explicit

Private Sub SetStatus(ByVal text As String)
    Dim ws As Worksheet
    On Error Resume Next
    Set ws = ThisWorkbook.Worksheets("Input")
    ws.Unprotect Password:=""
    ws.Range("B20").Value = text
    ws.Protect Password:="", UserInterfaceOnly:=True
End Sub

Public Sub RefreshDashboard()
    On Error GoTo Failed
    Application.ScreenUpdating = False
    If Not WorksheetExists("Dashboard") Then
        Err.Raise 5, , "Dashboard sheet missing"
    End If
    ' RefreshAll is safe with or without a PivotTable; calculate the model last.
    ThisWorkbook.RefreshAll
    Application.CalculateFullRebuild
    ThisWorkbook.Worksheets("Dashboard").Activate
    Application.ScreenUpdating = True
    SetStatus "Dashboard refreshed."
    Exit Sub
Failed:
    Application.ScreenUpdating = True
    SetStatus "Refresh failed: " & Err.Description
End Sub

Public Sub FilterAtRisk()
    Dim ws As Worksheet
    If Not WorksheetExists("Data") Then Exit Sub
    Set ws = ThisWorkbook.Worksheets("Data")
    If ws.AutoFilterMode Then ws.AutoFilterMode = False
    ws.Range("A1:K61").AutoFilter Field:=10, Criteria1:="At risk"
End Sub

Public Sub AddRecord()
    Dim wsIn As Worksheet, wsData As Worksheet
    Dim workstream As String, owner As String, status As String, priority As String
    Dim startDate As Variant, days As Variant, cost As Variant, benefit As Variant
    Dim lastRow As Long, nextRow As Long, nextId As String
    If Not WorksheetExists("Input") Or Not WorksheetExists("Data") Then Exit Sub
    Set wsIn = ThisWorkbook.Worksheets("Input")
    Set wsData = ThisWorkbook.Worksheets("Data")
    workstream = Trim(CStr(wsIn.Range("C6").Value))
    owner = Trim(CStr(wsIn.Range("F6").Value))
    startDate = wsIn.Range("C7").Value
    days = wsIn.Range("F7").Value
    cost = wsIn.Range("C8").Value
    benefit = wsIn.Range("F8").Value
    status = Trim(CStr(wsIn.Range("C9").Value))
    priority = Trim(CStr(wsIn.Range("F9").Value))

    If workstream = "" Or owner = "" Or status = "" Or priority = "" Then
        SetStatus "Chọn Workstream, Owner, Trạng thái và Ưu tiên."
        Exit Sub
    End If
    If Not IsDate(startDate) Then
        SetStatus "Ngày bắt đầu không hợp lệ."
        Exit Sub
    End If
    If Not IsNumeric(days) Then
        SetStatus "Số ngày phải là số."
        Exit Sub
    End If
    If CLng(days) < 1 Or CLng(days) > 365 Then
        SetStatus "Số ngày phải từ 1 đến 365."
        Exit Sub
    End If
    If Not IsNumeric(cost) Or Not IsNumeric(benefit) Then
        SetStatus "Chi phí và lợi ích phải là số."
        Exit Sub
    End If

    lastRow = wsData.Cells(wsData.Rows.Count, "A").End(xlUp).Row
    nextRow = lastRow + 1
    nextId = "T" & Format(lastRow, "000")
    wsData.Cells(nextRow, 1).Value = nextId
    wsData.Cells(nextRow, 2).Value = workstream
    wsData.Cells(nextRow, 3).Value = owner
    wsData.Cells(nextRow, 4).Value = CDate(startDate)
    wsData.Cells(nextRow, 5).Value = CDate(startDate) + CLng(days) - 1
    wsData.Cells(nextRow, 6).Value = CLng(days)
    wsData.Cells(nextRow, 7).Value = 0
    wsData.Cells(nextRow, 8).Value = CDbl(cost)
    wsData.Cells(nextRow, 9).Value = CDbl(benefit)
    wsData.Cells(nextRow, 10).Value = status
    wsData.Cells(nextRow, 11).Value = priority
    ClearForm
    Application.CalculateFullRebuild
    SetStatus "Đã thêm " & nextId & "."
End Sub

Public Sub ClearForm()
    Dim ws As Worksheet
    If Not WorksheetExists("Input") Then Exit Sub
    Set ws = ThisWorkbook.Worksheets("Input")
    ws.Range("C6").Value = ""
    ws.Range("F6").Value = ""
    ws.Range("C7").Value = Date
    ws.Range("F7").Value = 10
    ws.Range("C8").Value = 0
    ws.Range("F8").Value = 0
    ws.Range("C9").Value = "On track"
    ws.Range("F9").Value = "Medium"
End Sub

Private Function WorksheetExists(ByVal name As String) As Boolean
    Dim ws As Worksheet
    On Error Resume Next
    Set ws = ThisWorkbook.Worksheets(name)
    WorksheetExists = Not ws Is Nothing
    On Error GoTo 0
End Function
'''


def write_dashboard_module(path: str | Path) -> Path:
    path = Path(path)
    path.write_text(MODULE, encoding="utf-8")
    return path


def inject_vba(xlsx_path: str | Path, bas_path: str | Path) -> str | None:
    """Inject the module into a copy saved as .xlsm; returns None if blocked."""
    if sys.platform != "win32":
        return None
    try:
        import win32com.client as win32
    except Exception:
        return None
    xlsx_path = Path(xlsx_path).resolve()
    out = xlsx_path.with_suffix(".xlsm")
    excel = wb = None
    try:
        excel = win32.DispatchEx("Excel.Application")
        excel.Visible = False
        excel.DisplayAlerts = False
        wb = excel.Workbooks.Open(str(xlsx_path))
        # This raises if "Trust access to the VBA project object model" is off.
        project = wb.VBProject
        component = project.VBComponents.Add(1)  # vbext_ct_StdModule
        component.Name = "DashboardTools"
        component.CodeModule.AddFromString(Path(bas_path).read_text(encoding="utf-8"))
        wb.SaveAs(str(out), FileFormat=52)  # xlOpenXMLWorkbookMacroEnabled
        # Make the form buttons workbook-relative; SaveAs can leave the source
        # .xlsx name in OnAction, which then fails from the .xlsm.
        try:
            ws = wb.Worksheets("Input")
            for i in range(1, ws.Buttons().Count + 1):
                action = ws.Buttons(i).OnAction or ""
                if "!" in action:
                    ws.Buttons(i).OnAction = action.rsplit("!", 1)[-1]
            wb.Save()
        except Exception:
            pass
        return str(out)
    except Exception:
        return None
    finally:
        if wb is not None:
            try:
                wb.Close(False)
            except Exception:
                pass
        if excel is not None:
            try:
                excel.Quit()
            except Exception:
                pass


def normalize_button_macros(path: str | Path) -> bool:
    """Rewrite form-button macros to the workbook-relative ``[0]!`` form.

    XlsxWriter writes the source workbook name into ``FmlaMacro``. After
    SaveAs(.xlsm) that stale name can stop the button from running, so replace
    it with Excel's current-workbook reference.
    """
    import re
    import zipfile
    path = Path(path)
    if not path.is_file():
        return False
    changed = False
    with zipfile.ZipFile(path) as zin:
        members = {name: zin.read(name) for name in zin.namelist()}
    for name, blob in list(members.items()):
        if not name.endswith(".vml"):
            continue
        text = blob.decode("utf-8", errors="replace")
        new = re.sub(r"'[^']+'\.([A-Za-z_][A-Za-z0-9_]*\.)", r"[0]!\1", text)
        if new != text:
            members[name] = new.encode("utf-8")
            changed = True
    if changed:
        tmp = path.with_suffix(".macro.xlsm")
        with zipfile.ZipFile(tmp, "w", zipfile.ZIP_DEFLATED) as zout:
            for name, blob in members.items():
                zout.writestr(name, blob)
        tmp.replace(path)
    return changed


if __name__ == "__main__":
    import argparse
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument("xlsx", type=Path)
    p.add_argument("--bas", type=Path, default=None)
    p.add_argument("--inject", action="store_true")
    args = p.parse_args()
    bas = args.bas or args.xlsx.with_suffix(".bas")
    write_dashboard_module(bas)
    print(f"wrote {bas}")
    if args.inject:
        print(inject_vba(args.xlsx, bas) or "injection blocked or failed")
